/* From Uiverse.io by Creatlydev  - Tags: button, arrow, button, text, circular, modern, purple, interactive, css, awesome */
.__UIV_SCOPE__ .button {
  cursor: pointer;
  border: none;
  background: #7808d0;
  color: #fff;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  overflow: hidden;
  position: relative;
  display: grid;
  place-content: center;
  transition:
    background 300ms,
    transform 200ms;
  font-weight: 600;
}

.__UIV_SCOPE__ .button__text {
  position: absolute;
  inset: 0;
  animation: text-rotation 8s linear infinite;

  .__UIV_SCOPE__ > span {
    position: absolute;
    transform: rotate(calc(19deg * var(--index)));
    inset: 7px;
  }
}

.__UIV_SCOPE__ .button__circle {
  position: relative;
  width: 40px;
  height: 40px;
  overflow: hidden;
  background: #fff;
  color: #7808d0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .button__icon--copy {
  position: absolute;
  transform: translate(-150%, 150%);
}

.__UIV_SCOPE__ .button:hover {
  background: #000;
  transform: scale(1.05);
}

.__UIV_SCOPE__ .button:hover .button__icon {
  color: #000;
}

.__UIV_SCOPE__ .button:hover .button__icon:first-child {
  transition: transform 0.3s ease-in-out;
  transform: translate(150%, -150%);
}

.__UIV_SCOPE__ .button:hover .button__icon--copy {
  transition: transform 0.3s ease-in-out 0.1s;
  transform: translate(0);
}

@keyframes text-rotation {
  to {
    rotate: 360deg;
  }
}
